"""Two visual models over the immutable WEB-006 distribution, not a corpus redesign."""
import argparse,hashlib,html,json,math,re,tarfile,zipfile
from pathlib import Path

ICONS={'arrow':'M4 12h15m-6-6 6 6-6 6','book':'M12 5v16M3 3h5a4 4 0 0 1 4 4 4 4 0 0 1 4-4h5v16h-5a4 4 0 0 0-4 2 4 4 0 0 0-4-2H3Z','map':'m3 6 6-3 6 3 6-3v15l-6 3-6-3-6 3Zm6-3v15m6-12v15','search':'m21 21-5-5M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0','bag':'M8 6V4h8v2M5 6h14v15H5ZM5 11h14M9 15h6','compass':'M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0ZM16 8l-3 5-5 3 3-5Z','cross':'M10 3h4v7h7v4h-7v7h-4v-7H3v-4h7Z','shield':'M12 2 3 6v6c0 5 9 10 9 10s9-5 9-10V6Zm-5 9 3 3 7-7','route':'M6 5a3 3 0 1 0 0 .1Zm12 11a3 3 0 1 0 0 .1ZM9 5h6a4 4 0 0 1 0 8H9a4 4 0 0 0 0 8h6','menu':'M3 6h18M3 12h18M3 18h18'}
def icon(name,size=24):return f'<svg class="w7-icon" width="{size}" height="{size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.4" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="{ICONS[name]}"/></svg>'
def esc(s):return html.escape(str(s),quote=True)
def sha(b):return hashlib.sha256(b).hexdigest()

def build(a):
    assert sha(a.base.read_bytes())=='14c63e3194674968035529ec8044d673874a820243bd14797cdca9ee8b3fd411'
    assert not a.output.exists() and not a.registry.exists();a.output.mkdir(parents=True)
    z=zipfile.ZipFile(a.base)
    for n in z.namelist():
        assert not n.startswith('/') and '..' not in Path(n).parts
    z.extractall(a.output)
    root=a.output;index=json.loads(z.read('search-index.json'));byid={e['id']:e for e in index};manifest=json.loads(z.read('INTEGRITY.json'));assert len(index)==308
    assets=root/'media';(assets/'fonts').mkdir(parents=True);(assets/'licenses').mkdir()
    font_plan=[('sans-condensed',400,'ui-400'),('sans-condensed',600,'ui-600'),('serif',400,'read-400'),('serif',600,'read-600'),('mono',400,'mono-400')]
    registry=[];license_texts={}
    for family,weight,target in font_plan:
        archive=a.fonts/f'fontsource-ibm-plex-{family}-5.3.0.tgz';t=tarfile.open(archive)
        data=t.extractfile(f'package/files/ibm-plex-{family}-latin-{weight}-normal.woff2').read();(assets/'fonts'/f'{target}.woff2').write_bytes(data)
        license=t.extractfile('package/LICENSE').read();assert b'SIL OPEN FONT LICENSE' in license
        (assets/'licenses'/f'plex-{family}-OFL.txt').write_bytes(license);license_texts[family]=license.decode()
        registry.append({'asset':'fonts/'+target+'.woff2','purpose':'UI and reading typography','source':'@fontsource/ibm-plex-'+family+'@5.3.0','creator':'IBM Corp.','license':'OFL-1.1','rights_reviewed':True,'modified':False,'sha256':sha(data),'archive_sha256':sha(archive.read_bytes())})
    (assets/'models.css').write_text(Path('tools/web-007/models.css').read_text())
    (assets/'models.js').write_text(Path('tools/web-007/models.js').read_text())
    original=(root/'index.html').read_text();oldcss=re.search(r'<link\b[^>]*href="([^"]+\.css)"[^>]*>',original)[1]
    nav=[('Manual','/enciclopedia/'),('Supervivencia','/familias/MAN/'),('Equipo','/familias/EQP/'),('Combate','/familias/COM/'),('Chernarus','/atlas/chernarus/'),('Livonia','/atlas/livonia/'),('Guías','/familias/GUI/')]
    links=''.join(f'<a href="{url}">{label}</a>' for label,url in nav)
    brand='<a class="w7-brand" href="/" aria-label="DAYZ-SURVIVAL, inicio">DAYZ-SURVIVAL<small>THE CHERNARUS FIELD MANUAL</small></a>'
    header=f'<header class="w7-header"><div class="w7-header-inner">{brand}<nav class="desktop-nav" aria-label="Navegación principal">{links}<a class="w7-nav-search" href="/enciclopedia/" aria-label="Buscar en el manual">{icon("search",20)}</a></nav><details class="navigation"><summary aria-label="Menú de navegación">{icon("menu",22)}</summary><nav aria-label="Navegación principal móvil">{links}<a href="/enciclopedia/">Buscar en el manual</a></nav></details></div></header>'
    footer=f'<footer class="w7-footer"><div class="w7-container"><div class="w7-footer-top"><div>{brand}<p>Aprende el terreno. Prepárate bien.<br>Regresa con vida.</p></div><nav class="w7-footer-links" aria-label="Información del proyecto"><a href="/proyecto/">El proyecto</a><a href="/documentacion/">Documentación</a><a href="/licencias/">Créditos y recursos</a></nav></div><p class="w7-review-note">WEB-007 · Propuesta visual privada: portada y lector de ejemplo. El resto del catálogo conserva WEB-006. <a href="/revision/">Enviar observaciones mediante archivo local</a>.</p></div></footer>'
    def page(title,main):return f'<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><meta name="description" content="{esc(title)}. DAYZ-SURVIVAL, DayZ Standalone PC vanilla. Propuesta visual privada."><meta name="theme-color" content="#173629"><title>{esc(title)} · DAYZ-SURVIVAL</title><link rel="stylesheet" href="{oldcss}"><link rel="stylesheet" href="/media/models.css"></head><body class="web007"><a class="skip-link" href="#main-content">Saltar al contenido</a>{header}<main id="main-content" tabindex="-1">{main}</main>{footer}<script src="/media/models.js" defer></script></body></html>'
    def kicker(s):return '<p class="w7-kicker"><span class="w7-rule" aria-hidden="true"></span>'+s+'</p>'
    def story(id):
        entry=byid[id];source=(root/'articulos'/id/'index.html').read_text();body=re.search(r'<div class="manuscript">(.*?)</div>',source,re.S)[1];paragraphs=[html.unescape(re.sub('<[^>]+>','',p)) for p in re.findall(r'<p>(.*?)</p>',body,re.S)];plain=next((p for p in paragraphs if not re.match(r'(Título provisional|Borrador|Estado editorial)',p,re.I)),paragraphs[0])
        return f'<article class="w7-story">{kicker(entry["category"]+" / "+id)}<h3><a href="/articulos/{id}/">{esc(entry["title"])}</a></h3><p>{esc(plain)}</p><a href="/articulos/{id}/">Leer artículo completo {icon("arrow",18)}</a></article>'
    cards=[('01','MAN','Supervivencia','Para empezar a orientarte en el manual.','cross'),('02','EQP','Equipo','Conoce las piezas de tu inventario.','bag'),('03','COM','Combate','Consulta antes de tomar una decisión.','shield')]
    entries=''.join(f'<li class="w7-entry-card"><a href="/familias/{family}/"><div class="w7-card-top"><span>{number} / {family}</span>{icon(symbol,28)}</div><h3>{label}</h3><p>{description}</p></a></li>' for number,family,label,description,symbol in cards)
    atlas=''.join(f'<article class="w7-atlas-card"><div>{kicker("ATLAS INDEPENDIENTE / "+code)}<h3>{label}</h3><p>{count} expedientes de localidades, regiones e instalaciones.</p><a class="w7-text-link" href="/atlas/{route}/">Explorar {label} {icon("arrow",18)}</a></div><div class="w7-atlas-reserve" aria-hidden="true">{icon("map")}<span>IMAGEN<br>PENDIENTE<br>Sin cartografía</span></div></article>' for code,label,count,route in [('CHR','Chernarus',70,'chernarus'),('LIV','Livonia',14,'livonia')])
    hero=f'<section class="w7-hero"><div class="w7-container"><div class="w7-hero-grid"><div>{kicker("DAYZ STANDALONE / PC VANILLA")}<h1>Conoce el terreno.<br><em>Decide tu siguiente paso.</em></h1><p class="w7-intro">Un manual para encontrar respuestas, conocer tu equipo y explorar Chernarus y Livonia.</p><div class="w7-actions"><a class="w7-button" href="/articulos/MAN-01-01/">Tus primeros 15 minutos {icon("arrow",20)}</a><a class="w7-button ghost" href="/enciclopedia/">Abrir el manual {icon("book",20)}</a></div></div><figure class="w7-frame" data-media-slot="COVER"><div class="w7-frame-top"><span>ARCHIVE-86 / CUADERNO DE CAMPO</span><span>01</span></div><div class="w7-frame-void" aria-hidden="true"><span>86</span></div><figcaption><strong>Portada de campo.</strong>Reserva para una captura vanilla o un original a grafito. Imagen pendiente; no contiene cartografía.</figcaption></figure></div><div class="w7-hero-tail"><p>308 artículos completos. Un mismo cuaderno de consulta.</p><span>CHERNARUS PLUS / LIVONIA</span></div></div></section>'
    search=f'<section class="w7-search-band"><div class="w7-container w7-search-inner"><p>¿Qué necesitas consultar?</p><form class="w7-search-form" action="/enciclopedia/" role="search"><label for="home-search">Buscar en los 308 artículos</label><input id="home-search" type="search" name="q" maxlength="200" placeholder="Un tema, un objeto, un lugar…"><button type="submit">Buscar {icon("search",18)}</button></form></div></section>'
    home=hero+search+f'<section class="w7-section w7-reveal"><div class="w7-container"><div class="w7-section-head"><div>{kicker("UNA CONSULTA, UN SIGUIENTE PASO")}<h2>Empieza por lo que importa.</h2></div><a class="w7-text-link" href="/familias/GUI/">Guías prácticas {icon("arrow",18)}</a></div><ul class="w7-entry-grid">{entries}</ul><div class="w7-small-topics"><span>También en tu cuaderno:</span><a href="/familias/MEC/">Mecánicas {icon("arrow",16)}</a><a href="/familias/GUI/">Guías prácticas {icon("arrow",16)}</a></div></div></section><section class="w7-section w7-atlas-section w7-reveal"><div class="w7-container"><div class="w7-section-head"><div>{kicker("DOS TERRITORIOS, DOS ATLAS")}<h2>Elige dónde mirar.</h2></div></div><div class="w7-atlas-grid">{atlas}</div></div></section><section class="w7-section w7-reveal"><div class="w7-container"><div class="w7-section-head"><div>{kicker("LECTURAS PARA EL CAMINO")}<h2>Abre el manual.</h2></div></div><div class="w7-story-grid">{story("MAN-01-01")}{story("EQP-01-01")}{story("COM-01-01")}</div></div></section>'
    (root/'index.html').write_text(page('Conoce el terreno',home))
    source=(root/'articulos/MAN-01-01/index.html').read_text();body=re.search(r'<div class="manuscript">(.*?)</div>',source,re.S)[1]
    outline=re.search(r'<aside class="outline">(.*?)</aside>',source,re.S)[1]
    metadata=re.search(r'<section id="document-record" class="document-record">(.*?)</section>',source,re.S)[1]
    entry=byid['MAN-01-01'];first=html.unescape(re.sub('<[^>]+>','',re.search(r'<p>(.*?)</p>',body,re.S)[1]))
    controls='<div class="reader-tools"><span class="reader-label">LECTURA DE CAMPO / MAN-01-01</span><div class="size-controls"><span class="tool-label">TEXTO</span><button id="text-smaller" type="button" aria-controls="reader-content" aria-disabled="true" aria-label="Reducir tamaño del texto">A−</button><button id="text-larger" type="button" aria-controls="reader-content" aria-disabled="false" aria-label="Aumentar tamaño del texto">A+</button></div></div><p class="sr-only" id="text-size-status" role="status" aria-live="polite" aria-atomic="true"></p>'
    cover=f'<div class="w7-container"><nav class="w7-breadcrumb" aria-label="Ruta de navegación"><a href="/">Inicio</a> / <a href="/familias/MAN/">Supervivencia</a> / MAN-01-01</nav><div class="w7-article-cover"><div>{kicker("SUPERVIVENCIA / PRIMEROS PASOS")}<p class="w7-article-title">{esc(entry["title"])}</p><p class="w7-intro">{esc(first)}</p><div class="w7-actions"><a class="w7-button" href="#reader-content">Empezar a leer {icon("arrow",20)}</a></div><div class="w7-reading-meta"><span>MAN-01-01</span><span>Lectura extensa</span><a href="#document-record">Procedencia y estado</a></div></div><figure class="w7-graphite-reserve" data-media-slot="MAN-01-01"><div class="w7-graphite-void" aria-hidden="true"><span>CUADERNO DE CAMPO<br>MAN / 01</span></div><figcaption>Reserva para grafito original vinculado a este artículo. Ilustración pendiente; no representa equipo, mecánicas ni terreno verificados.</figcaption></figure></div></div>'
    reader=f'{cover}<div class="w7-paper"><div class="w7-container w7-reading-grid"><aside class="w7-outline">{outline}</aside><article id="reader-content" class="reader w7-reader">{controls}<div class="manuscript">{body}</div><details id="document-record" class="w7-record"><summary>Procedencia y estado de este artículo</summary><section class="document-record">{metadata}</section></details><section class="w7-next-read"><h2>Sigue explorando</h2><a href="/articulos/MAN-01-02/">{esc(byid["MAN-01-02"]["title"])} {icon("arrow",18)}</a><a href="/familias/MAN/">Todo el capítulo de supervivencia {icon("arrow",18)}</a></section></article></div></div>'
    (root/'articulos/MAN-01-01/index.html').write_text(page(entry['title'],reader))
    doc=f'<div class="w7-paper"><div class="w7-container">{kicker("REFERENCIAS / SECCIÓN SECUNDARIA")}<h1>Documentación del proyecto</h1><p class="w7-doc-intro">Los contenidos documentales siguen accesibles. Se mantienen separados de la navegación principal para jugadores. Una aprobación editorial no certifica mecánicas de juego.</p><ul class="w7-document-list"><li><a href="/familias/ARC/">Archivo técnico · cinco artículos completos</a></li><li><a href="/INTEGRITY.json">Manifiesto de integridad y estados de origen</a></li><li><a href="/revision/">Hoja de evaluación y exportación local</a></li><li><a href="/licencias/">Procedencia de recursos y licencias</a></li></ul><p>La colección mantiene 294 IDs históricos y 14 LIV independientes. Los estados editoriales y la evidencia técnica de cada artículo permanecen en su ficha documental.</p></div></div>'
    (root/'documentacion').mkdir();(root/'documentacion/index.html').write_text(page('Documentación del proyecto',doc))
    credits=f'<div class="w7-paper"><div class="w7-container"><h1>Recursos y procedencia</h1><p>WEB-007 propone dos modelos visuales. No incorpora fotografías, cartografía ni ilustraciones finales. Las reservas se identifican como pendientes y no aportan evidencia de DayZ.</p><h2>Tipografía</h2><p>IBM Plex Sans Condensed, IBM Plex Serif e IBM Plex Mono; IBM Corp.; paquetes Fontsource 5.3.0. Archivos sin modificar, alojados localmente y embebidos en la versión autónoma. Licencia SIL Open Font License 1.1; sin dependencias remotas.</p><ul>{"".join(f"<li><a href='/media/licenses/plex-{family}-OFL.txt'>Licencia IBM Plex {family}</a></li>" for family in license_texts)}</ul><h2>Iconos y material de interfaz</h2><p>Geometría SVG editable del sistema de interfaz, reutilizada y ampliada con asistencia de Codex. Retícula de 24 unidades y trazo común. No es ilustración editorial final ni documento del juego. El papel, marcos y fondos son CSS no figurativo; no representan paisaje ni mapa.</p><h2>Ilustraciones futuras</h2><p>308 plazas por artículo, una portada y ocho separadores. Cada pieza requiere propósito, original, procedencia, derechos revisados, alternativa accesible y aprobación independiente. No se ha completado ninguna de estas imágenes en esta propuesta.</p></div></div>'
    (root/'licencias').mkdir();(root/'licencias/index.html').write_text(page('Recursos y procedencia',credits))
    for n in z.namelist():
        if n not in ('index.html','articulos/MAN-01-01/index.html'):assert (root/n).read_bytes()==z.read(n),n
    slots=[{'asset_id':e['id'],'content_id':e['id'],'type':'original-graphite','purpose':'Ilustración vinculada al artículo','status':'PENDING','path':None,'source':None,'license':None,'rights_reviewed':False,'alt_reviewed':False,'approved':False} for e in index]
    slots += [{'asset_id':name,'content_id':None,'type':'original-cover' if name=='COVER' else 'section-divider','status':'PENDING','path':None,'source':None,'license':None,'rights_reviewed':False,'alt_reviewed':False,'approved':False} for name in ['COVER']+['DIVIDER-'+f for f in ['MAN','COM','EQP','CHR','MEC','GUI','ARC','LIV']]]
    for slot in slots:
        slot.update({'creator':None,'source_game_build':None,'source_map':byid[slot['content_id']]['map'] if slot['content_id'] else None,'alt_draft':None,'caption_draft':None,'source_original_sha256':None,'derivatives':[],'planned_ratio':'3:2' if slot['content_id'] else ('16:9' if slot['asset_id']=='COVER' else '3:1'),'publication_authorized':False,'requires':['editorial purpose','authentic original','rights review','accessible description','map/build context when applicable','explicit publication approval']})
    a.registry.write_text(json.dumps({'contract':'WEB-007','visual_models':['/','/articulos/MAN-01-01/'],'unchanged_article_pages':307,'slots':slots,'fonts':registry,'final_images_included':0,'approved_illustrations':0},ensure_ascii=False,indent=2))
    print(json.dumps({'articles':308,'redesigned_articles':1,'unchanged_articles':307,'visual_models':2,'illustration_slots':len(slots),'fonts':len(registry)}))

if __name__=='__main__':
    p=argparse.ArgumentParser()
    for key in ['base','fonts','output','registry']:p.add_argument('--'+key,type=Path,required=True)
    build(p.parse_args())
